import numpy as np
def matrix_mult_mod(A, B, mod):
    return (np.dot(A, B) % mod)
def matrix_pow_mod(M, n, mod):
    result = np.identity(len(M), dtype=int)
    base = M.copy()

    while n > 0:
        if n % 2 == 1:
            result = matrix_mult_mod(result, base, mod)
        base = matrix_mult_mod(base, base, mod)
        n //= 2

    return result
def solve(inputs):
    M = inputs.get('M')
    n = inputs.get('n')
    mod = inputs.get('mod')

    power_matrix = matrix_pow_mod(M, n, mod)
    return sum(sum(row) for row in power_matrix)

